    max by (cluster, namespace, pod, container)(container_memory_working_set_bytes{cluster="", namespace="cosmotech-recovery", container!="", image!=""})
  * on(cluster, namespace, pod)
    group_left(workload, workload_type) namespace_workload_pod:kube_pod_owner:relabel{cluster="", namespace="cosmotech-recovery", workload=~"", workload_type=~""}
) by (pod)
/sum(
    max by (cluster, namespace, pod, container)(kube_pod_container_resource_limits{job="kube-state-metrics", cluster="", namespace="cosmotech-recovery", resource="memory"})
  * on(cluster, namespace, pod)
    group_left(workload, workload_type) namespace_workload_pod:kube_pod_owner:relabel{cluster="", namespace="cosmotech-recovery", workload=~"", workload_type=~""}
) by (pod)

targets.raw_query:
sort_desc(
  sum by (workload, workload_type) (
    sum by (cluster, namespace, pod) (8 * rate(container_network_receive_bytes_total{cluster="$cluster",namespace="$namespace"}[$__rate_interval]))
    * on (cluster, namespace, pod)
    topk by (cluster, namespace, pod) (
      1,
      max by (cluster, namespace, pod) (kube_pod_info{cluster="$cluster",namespace="$namespace",host_network="false"})
    )
    * on (cluster, namespace, pod) group_left (workload, workload_type)
    namespace_workload_pod:kube_pod_owner:relabel{cluster="$cluster",namespace="$namespace", workload=~".+", workload_type=~"$type"}
  )
)

